'use strict';
const $=s=>document.querySelector(s),KEY='seoul-study-club-v1';
let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')}catch{}
let relationGroups=[],relationView='compare',relationQuiz=null,migrationPerformed=false;
let words=[],category='All words',mode='plan',deck=[],index=0,flipped=false,reviewed=new Set(),quiz=null,search='',libPage=0,noteOnly=false;
const state={learned:{},mistakes:[],daily:{},plan:{},practice:{},linkPractice:{},customWords:[],referenceNotes:[],updatedAt:0,exam:'2026-10-17',...saved};
let collection={rows:422,pages:Array.from({length:14},(_,i)=>String(7785+i)),photos:14};
const practice=w=>state.practice[w.id]||{known:0,again:0,forgotten:0};
const practiceLabel=w=>{const p=practice(w);return `SEEN ${p.known+p.again} TIMES · ✓ KNOWN ${p.known} · ↺ AGAIN ${p.again}${p.forgotten?' · FORGOT '+p.forgotten+'×':''}`};
const snapshot=()=>({version:2,app:'seoul-study-club',state:JSON.parse(JSON.stringify(state))});
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Dubai'});
const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const learned=w=>state.learned[w.id]??w.learned;
const save=()=>{state.updatedAt=Date.now();try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Browser storage is unavailable. Download a progress backup.')}storage.changed();window.DashboardOverview?.render()};
const motivations=['You don’t need to know everything today. You only need to begin.','틀려도 괜찮아. Mistakes are directions for your next review.','A daily hour can hold a lot of small wins. This is one of them.','You’ve already done the brave part: finding what you don’t know.','천천히, 꾸준히. Slowly and steadily. You’re getting there.','A word you miss today can be a point you earn on exam day.','Take a sip of water. Relax your shoulders. Try one more card.','Your exam is a moment. Your effort is something you keep.','조금씩 좋아지고 있어. You’re getting better, little by little.','You don’t have to feel ready to make progress. Keep going.'];
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3000)}
function matches(w,c=category){const old=window.StudyHub.isLegacy(w);if(c==='All words')return old;if(c==='Yesterday words')return window.StudyEngine.yesterdayWords([w],today()).length>0;if(c==='Vocabulary')return !w.hanjaRef&&w.studyRef?.kind!=='grammar';if(c.startsWith('Hanja readings:'))return !!w.hanjaRef&&!w.hanjaRef.vocabulary&&w.hanjaRef.chapter===+c.split(':')[1];if(c==='Hanja')return !!w.hanjaRef;if(c==='Hanja reviews')return !!w.hanjaRef&&window.StudyHub.due(w);if(['Daily review','Due reviews'].includes(c))return window.StudyHub.dailyBatch().some(x=>x.id===w.id);if(c.startsWith('Book vocabulary:')||c.startsWith('Book grammar:')){const [kind,chapter,day]=c.split(':');return !!w.studyRef&&w.studyRef.kind===kind.replace('Book ','')&&w.studyRef.chapter===+chapter&&(day==='all'||w.studyRef.date===day)}if(c.startsWith('Book day '))return w.studyRef?.date===c.slice(9);return old&&(c==='IMPORTANT WORDS'&&w.important||c==='Learned words'&&learned(w)||c==='My mistakes'&&state.mistakes.includes(w.id)||c==='Forgotten after learning'&&practice(w).forgotten>0||c==='Check these notes'&&w.note||w.categories.includes(c))||!!w.hanjaRef&&w.categories.includes(c)}
function filtered(){return words.filter(w=>matches(w)&&(!$('#unlearned').checked||!learned(w)))}
function stats(){
 window.DashboardOverview.render();
 categories();$('#stackCount').textContent=`${filtered().length} cards`;
}
function categories(){const oldWords=words.filter(window.StudyHub.isLegacy),names=[...new Set(['All words','IMPORTANT WORDS','Learned words','My mistakes','Forgotten after learning','Synonyms','Antonyms','Word families',...new Set(oldWords.flatMap(w=>w.categories)),'Check these notes'])],wasOpen=$('#topikOneStacks')?.open||false;
 $('#categoryList').innerHTML=`<div class="hub-sidebar"><button class="category" data-hubnav="today"><span>⌂</span> Today</button><button class="category" data-hubnav="progress"><span>◔</span> My progress</button><button class="category" data-hubnav="hanja"><span>字</span> Hanja</button><button class="category" data-hubnav="notes"><span>▤</span> Book notes</button><button class="category" data-hubnav="rules"><span>▣</span> Rules</button><button class="category" data-hubnav="grammar"><span>ㄴ</span> Grammar structures</button><button class="category" id="vocabularySidebar"><span>가</span> Vocabulary</button><button class="category" data-hubnav="calendar"><span>▦</span> Calendar</button></div><details id="topikOneStacks" ${wasOpen?'open':''}><summary>TOPIK I vocabulary</summary>${names.map((c,i)=>`<button class="category ${category===c&&mode!=='plan'?'active':''}" data-cat="${e(c)}"><span>${e(c)}</span><small>${oldWords.filter(w=>matches(w,c)).length}</small></button>`).join('')}</details>`;
 document.querySelectorAll('[data-hubnav]').forEach(b=>{b.classList.toggle('active',mode==='plan'&&(window.StudyHub.currentView()===b.dataset.hubnav||b.dataset.hubnav==='progress'&&['books','milestones'].includes(window.StudyHub.currentView())));b.onclick=()=>{closeMenu();window.StudyHub.open(b.dataset.hubnav)}});$('#vocabularySidebar').onclick=()=>{closeMenu();window.StudyHub.openStack('Vocabulary')};$('#categoryList').querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{closeMenu();category=b.dataset.cat;mode=['Synonyms','Antonyms'].includes(category)?'links':'cards';$('#unlearned').checked=false;resetDeck();render()});
}
function resetDeck(){window.TypingPractice?.reset();deck=filtered();index=0;flipped=false;reviewed=new Set();quiz=null;relationQuiz=null;search='';libPage=0}
function record(w){if(!w)return;const set=new Set(state.daily[today()]||[]);set.add(w.id);state.daily[today()]=[...set];reviewed.add(w.id);save();stats();$('#motivationText').textContent=motivations[Math.floor(set.size/10)%motivations.length]}
function mark(w,val){const before=learned(w),p=state.practice[w.id]||{known:0,again:0,forgotten:0,history:[]};
 if(val)p.known++;else{p.again++;if(before)p.forgotten++;if(!state.mistakes.includes(w.id))state.mistakes.push(w.id)}
 p.lastAction=val?'known':'again';p.lastAt=new Date().toISOString();p.history=[...(p.history||[]),{action:p.lastAction,at:p.lastAt,forgotten:!val&&before}].slice(-100);state.practice[w.id]=p;
 window.StudyHub.schedule(w,val);state.learned[w.id]=val;if(val)state.mistakes=state.mistakes.filter(x=>x!==w.id);save();stats()}

function mistake(w){if(!state.mistakes.includes(w.id))state.mistakes.push(w.id);save();stats()}
function render(){stats();$('.tabs').hidden=mode==='plan';$('#stackTitle').textContent=category.startsWith('Book vocabulary:')?'Chapter '+category.split(':')[1]+' · Vocabulary':category.startsWith('Book grammar:')?'Chapter '+category.split(':')[1]+' · Grammar':category.startsWith('Hanja readings:')?'Hanja · Chapter '+category.split(':')[1]+' · Readings':category;$('.tabs').querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-current',b.dataset.mode===mode?'page':'false')});$('#controls').style.display=['plan','links'].includes(mode)?'none':'flex';$('#shuffle').style.display=mode==='cards'?'inline-block':'none';if(mode==='cards')renderCard();else if(mode==='quiz')renderQuiz();else if(mode==='typing')window.TypingPractice.render();else if(mode==='library')renderLibrary();else if(mode==='links')renderRelations();else window.StudyHub.render()}
function empty(){return `<div class="empty">No cards in this stack yet ˙ᵕ˙<br>Try All words or switch off “Still learning only”.</div>`}
function memoryHintMarkup(w,open=false){const h=w.memoryHint;if(!h)return '';return `<details class="memory-hint" ${open?'open':''}><summary>✳ Memory hint <span>${e(h.type)}</span></summary><p>${e(h.text)}</p>${h.dictionaryUrl?`<a href="${e(h.dictionaryUrl)}" target="_blank" rel="noopener">Dictionary word / origin ↗</a>`:''}<small>${h.type==='Sound trick'?'A made-up sound association, not the word’s origin. Keep the Korean spelling as your pronunciation guide.':'A word link or mental picture to recall the meaning; the picture itself is a memory aid.'}</small></details>`}
const extraForms=w=>w.forms.filter(f=>!w.korean.split(' / ').includes(f));
function renderCard(){
 const box=$('#studyContent');if(!deck.length){box.innerHTML=empty();return}index=Math.max(0,Math.min(index,deck.length-1));const w=deck[index];
 box.innerHTML=`<div class="card-meta"><span>CARD ${String(index+1).padStart(3,'0')} / ${deck.length}</span><span>${w.hanjaRef?`HANJA · CHAPTER ${w.hanjaRef.chapter}`:w.studyRef?`BOOK · CHAPTER ${w.studyRef.chapter} · ${w.studyRef.date}`:w.important?`★ NOTEBOOK ${w.count}×`:'FROM YOUR NOTEBOOK'} ${learned(w)?' · ✓ LEARNED':''}</span></div><div class="practice-meta">${e(practiceLabel(w))}</div><div class="card-shell"><button class="flashcard" id="flip" aria-label="${flipped?'Show Korean':'Reveal translation'}"><span class="card-language">${flipped?(w.note?'CHECKED MEANING · ENGLISH / РУССКИЙ':'YOUR PAPER · ENGLISH / РУССКИЙ'):(w.hanjaReading?'HANJA · RECALL THE KOREAN READING':'한국어 · KOREAN')}</span><span class="${flipped?'answer':'korean'}" lang="${flipped?'':'ko'}">${e(flipped?(w.hanjaReading?w.answer:w.note?w.quizAnswer:w.answer):w.korean)}</span>${!flipped&&extraForms(w).length?`<span class="forms" lang="ko">Also written: ${e(extraForms(w).join(' · '))}</span>`:''}<span class="flip-hint">${flipped?'↻ CLICK TO SEE KOREAN':'↻ CLICK TO FLIP · SPACE ON KEYBOARD'}</span></button>${w.studyRef?'<button class="small-btn" id="pronounceCard">🔊 Listen in Korean</button>':''}${memoryHintMarkup(w,flipped)}${flipped?`<div class="card-details">${w.note?`<div class="study-note"><strong>Study note · ${e(w.quizAnswer)}</strong><br>${e(w.note)}<br><small>${w.hanjaRef||w.studyRef?'Book entry':'Written on paper'}: ${e(w.answer)}</small>${w.dictionaryUrl?`<br><a href="${e(w.dictionaryUrl)}" target="_blank" rel="noopener">Official dictionary ↗</a>`:''}</div>`:''}<button class="source-link" id="cardSource">${w.hanjaRef?'Book · p.'+w.hanjaRef.page:w.studyRef?'Book notes · '+w.studyRef.date:'Check original · '+w.sourcePages.map(sourceLabel).join(', ')}</button></div>`:''}</div><div class="card-actions"><button class="btn" id="again">↑ Learn again</button><button class="btn primary" id="know">↓ ${learned(w)?'Still know it':'I know this'}</button>${learned(w)?'<button class="text-link" id="unlearn">Still learning</button>':''}</div><div class="navigation"><button id="prev" ${index===0?'disabled':''}>← Previous</button><div class="progress"><i style="width:${(index+1)/deck.length*100}%"></i></div><button id="next">${index===deck.length-1?'Finish stack ✓':'Next →'}</button></div>`;
 if($('#pronounceCard'))$('#pronounceCard').onclick=()=>window.BookNotes.pronounce(w.pronunciation||w.korean);$('#flip').onclick=()=>{flipped=!flipped;if(flipped)record(w);renderCard()};$('#prev').onclick=()=>{index--;flipped=false;renderCard()};$('#next').onclick=nextCard;
 $('#know').onclick=()=>{mark(w,true);record(w);nextCard()};$('#again').onclick=()=>{mark(w,false);mistake(w);record(w);nextCard()};if($('#unlearn'))$('#unlearn').onclick=()=>{mark(w,false);renderCard()};if($('#cardSource'))$('#cardSource').onclick=()=>sources(w.sourcePages,w);
}
function nextCard(){if(index<deck.length-1){index++;flipped=false;renderCard()}else{$('#studyContent').innerHTML=`<div class="result"><div class="eyebrow">STACK COMPLETE · 수고했어요</div><h2>One lovely little win.</h2><p>You reached the end of ${deck.length} cards.<br>You reviewed ${reviewed.size} distinct cards in this pass.</p><button class="btn primary" id="repeatStack">↻ Shuffle and repeat</button> <button class="btn" id="testStack">Test this stack →</button></div>`;$('#repeatStack').onclick=()=>{deck=shuffle(filtered());index=0;flipped=false;reviewed=new Set();renderCard()};$('#testStack').onclick=()=>{mode='quiz';quiz=null;render()}}}
function renderQuiz(){
 if(quiz?.finished){renderResults();return}if(quiz){question();return}const pool=filtered();if(!pool.length){$('#studyContent').innerHTML=empty();return}if(pool.every(w=>w.studyRef?.kind==='grammar')&&new Set(words.filter(w=>w.studyRef?.kind==='grammar').map(w=>w.quizAnswer)).size<2){$('#studyContent').innerHTML='<div class="empty">Use flashcards to practise this grammar structure. A choice quiz will be available after you add more grammar structures.</div>';return}
 $('#studyContent').innerHTML=`<div class="quiz-start"><div class="eyebrow">NO PRESSURE. JUST PRACTICE.</div><h3>Let’s see what stuck.</h3><p>${pool.every(w=>w.hanjaReading)?'Read the character and choose its Korean pronunciation.':'Choose the meaning. Missed words are saved for review.'}</p><label for="quizSize">Questions </label><select id="quizSize"><option value="10">10 · a small warm-up</option><option value="20">20 · a solid session</option><option value="all">All ${pool.length} · full stack</option></select><button id="startQuiz" class="btn primary">Start test →</button><p>Quiz answers don’t change your learned marks. That choice stays yours.</p></div>`;
 $('#startQuiz').onclick=()=>{const n=$('#quizSize').value;quiz={items:shuffle(pool).slice(0,n==='all'?pool.length:+n),at:0,results:[],answered:false,finished:false};question()};
}
const norm=s=>s.toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();
function choicesFor(w){const same=a=>norm(a)===norm(w.quizAnswer);const candidates=shuffle(words.filter(x=>x.id!==w.id&&!same(x.quizAnswer)&&!!x.hanjaRef===!!w.hanjaRef&&((x.studyRef?.kind==='grammar')===(w.studyRef?.kind==='grammar'))&&(!w.hanjaRef||!!x.hanjaRef.vocabulary===!!w.hanjaRef.vocabulary)));const seen=new Set([norm(w.quizAnswer)]),others=[];const correctTokens=new Set(w.quizAnswer.toLowerCase().split(/\s*[•/,()]\s*/).map(norm).filter(Boolean));for(const x of candidates){const t=norm(x.quizAnswer);const overlaps=x.quizAnswer.toLowerCase().split(/\s*[•/,()]\s*/).map(norm).some(t=>correctTokens.has(t));if(!seen.has(t)&&!overlaps){others.push(x.quizAnswer);seen.add(t)}if(others.length===3)break}return shuffle([w.quizAnswer,...others])}
function question(){
 const w=quiz.items[quiz.at];if(!quiz.answered)quiz.choices=choicesFor(w);
 $('#studyContent').innerHTML=`<div class="card-meta"><span>QUESTION ${quiz.at+1} / ${quiz.items.length}</span><span>${quiz.results.filter(r=>r.correct).length} CORRECT</span></div><div class="quiz-word"><div class="card-language">${w.hanjaReading?'HOW IS THIS READ IN KOREAN?':'WHAT DOES THIS MEAN?'}</div><div class="korean" lang="ko">${e(w.korean)}</div>${extraForms(w).length?`<div class="forms">${e(extraForms(w).join(' · '))}</div>`:''}</div>${memoryHintMarkup(w)}<div class="choices">${quiz.choices.map((a,i)=>`<button class="choice ${quiz.answered?(a===w.quizAnswer?'correct':a===quiz.selected?'wrong':''):''}" data-i="${i}" ${quiz.answered?'disabled':''}><span>${i+1}</span>${e(a)}</button>`).join('')}</div>${quiz.answered?`<div class="feedback"><strong>${quiz.selected===w.quizAnswer?'✓ 맞았어요! Well done.':'↺ Almost. This one is worth another look.'}</strong><br>${e(w.korean)} → ${e(w.hanjaReading?w.answer:w.quizAnswer)}${w.note?`<div class="study-note">${e(w.note)}<br>${w.hanjaRef||w.studyRef?'Book entry':'Paper'}: ${e(w.answer)}</div>`:''}<button class="source-link" id="quizSource">${w.hanjaRef?'View book entry':'View original notebook entry'}</button></div><button id="quizNext" class="btn primary">${quiz.at===quiz.items.length-1?'See results':'Next question →'}</button>`:''}`;
 if(!quiz.answered)document.querySelectorAll('.choice').forEach(b=>b.onclick=()=>answerQuiz(+b.dataset.i));else{$('#quizNext').onclick=()=>{quiz.at++;quiz.answered=false;if(quiz.at>=quiz.items.length){quiz.finished=true;renderResults()}else question()};$('#quizSource').onclick=()=>sources(w.sourcePages,w)}
}
function answerQuiz(i){if(!quiz||quiz.answered)return;const w=quiz.items[quiz.at],a=quiz.choices[i];if(a===undefined)return;quiz.selected=a;quiz.answered=true;quiz.results.push({id:w.id,correct:a===w.quizAnswer,selected:a});window.StudyHub.schedule(w,a===w.quizAnswer);record(w);if(a!==w.quizAnswer)mistake(w);else{state.mistakes=state.mistakes.filter(id=>id!==w.id);save();stats()}question()}
function renderResults(){const wrong=quiz.results.filter(r=>!r.correct);$('#studyContent').innerHTML=`<div class="result"><div class="eyebrow">TEST COMPLETE · 잘했어요</div><div class="score">${quiz.results.length-wrong.length}<small style="font-size:23px"> / ${quiz.results.length}</small></div><h2>${wrong.length?'Every mistake is a word to win back.':'Look at you. Every single one. ˙ᵕ˙'}</h2><p>${wrong.length?wrong.length+' words to revisit. You’re closer than when you started.':'Take a breath and enjoy that little victory.'}</p><button class="btn primary" id="newQuiz">New test →</button>${wrong.length?' <button class="btn" id="retryQuiz">Retry only mistakes</button>':''}${wrong.map(r=>{const w=words.find(w=>w.id===r.id);return `<div class="mistake-row"><strong>${e(w.korean)}</strong> → ${e(w.quizAnswer)}<br><small>Your answer: ${e(r.selected)}</small></div>`}).join('')}</div>`;$('#newQuiz').onclick=()=>{quiz=null;renderQuiz()};if($('#retryQuiz'))$('#retryQuiz').onclick=()=>{quiz={items:shuffle(wrong.map(r=>words.find(w=>w.id===r.id))),at:0,results:[],answered:false,finished:false};question()}}
function renderLibrary(){const pool=filtered().filter(w=>(!noteOnly||w.note)&&norm([w.korean,...w.forms,w.answer,w.quizAnswer,w.memoryHint?.text||''].join(' ')).includes(norm(search)));const pages=Math.max(1,Math.ceil(pool.length/25));libPage=Math.min(libPage,pages-1);
 $('#studyContent').innerHTML=`<input class="search" id="search" type="search" placeholder="Search Korean, English or русский…" aria-label="Search word library" value="${e(search)}"><div class="library-controls"><span>${pool.length} matching cards · ${collection.rows} original notebook rows preserved; Hanja entries cite book pages</span><label class="check"><input id="noteOnly" type="checkbox" ${noteOnly?'checked':''}> Translation notes only</label></div><div class="word-list">${pool.slice(libPage*25,libPage*25+25).map(w=>`<div class="word-row"><div><strong lang="ko">${e(w.korean)}</strong><small>${w.important?'★ '+w.count+' appearances · ':''}${learned(w)?'✓ Learned':'Still learning'}</small><small>${e(practiceLabel(w))}</small>${extraForms(w).length?`<small>${e(w.forms.join(' · '))}</small>`:''}</div><div class="meaning">${e(w.note?w.quizAnswer:w.answer)}${w.note?`<small>${w.hanjaRef||w.studyRef?'Book entry':'Paper'}: ${e(w.answer)}</small>`:''}${w.note?`<details><summary class="badge">Study note</summary><p translate="no">${e(w.note)}</p><strong>Quiz: ${e(w.quizAnswer)}</strong></details>`:''}${memoryHintMarkup(w)}</div><div><button data-source="${e(w.id)}">${w.hanjaRef||w.studyRef?'Book':'Paper'} ↗</button>${w.custom?`<br><button data-library-edit="${e(w.id)}">Edit / delete</button>`:''}<br><button data-learn="${e(w.id)}" style="margin-top:6px" aria-label="${learned(w)?'Mark still learning':'Mark learned'} ${e(w.korean)}">${learned(w)?'✓':'＋'} Learned</button></div></div>`).join('')||empty()}</div><div class="pagination"><button class="small-btn" id="libPrev" ${libPage===0?'disabled':''}>←</button><span>PAGE ${libPage+1} / ${pages}</span><button class="small-btn" id="libNext" ${libPage===pages-1?'disabled':''}>→</button></div>`;
 $('#search').oninput=ev=>{const pos=ev.target.selectionStart;search=ev.target.value;libPage=0;renderLibrary();$('#search').focus();$('#search').setSelectionRange(pos,pos)};$('#noteOnly').onchange=ev=>{noteOnly=ev.target.checked;libPage=0;renderLibrary()};$('#libPrev').onclick=()=>{libPage--;renderLibrary()};$('#libNext').onclick=()=>{libPage++;renderLibrary()};document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>{const w=words.find(w=>w.id===b.dataset.source);sources(w.sourcePages,w)});document.querySelectorAll('[data-library-edit]').forEach(b=>b.onclick=()=>window.Vocabulary.edit(b.dataset.libraryEdit));document.querySelectorAll('[data-learn]').forEach(b=>b.onclick=()=>{const w=words.find(w=>w.id===b.dataset.learn);mark(w,!learned(w));renderLibrary()})}
function relationPool(){const type=['Synonyms','Antonyms'].includes(category)?category:'Synonyms';return relationGroups.filter(g=>g.type===type)}
function renderRelations(){const pool=relationPool(),type=pool[0]?.type||'Synonyms';$('#stackCount').textContent=`${pool.length} groups`;
 const intro=`<div class="relation-toolbar"><div><button class="small-btn ${type==='Synonyms'?'selected':''}" data-reltype="Synonyms">≈ Synonyms</button><button class="small-btn ${type==='Antonyms'?'selected':''}" data-reltype="Antonyms">↔ Antonyms</button></div><div><button class="small-btn" id="compareLinks">Study pairs</button><button class="small-btn" id="quizLinks">Test pairs</button></div></div><p class="relation-intro">${type==='Synonyms'?'Words with the same or similar meanings. “Near” groups include a note explaining the difference.':'Opposite meanings, with the relevant sense kept clear.'} <small>“Extra comparison” marks a useful word outside your personal deck.</small></p>`;
 $('#studyContent').innerHTML=intro+'<div id="relationBody"></div>';
 document.querySelectorAll('[data-reltype]').forEach(b=>b.onclick=()=>{category=b.dataset.reltype;relationQuiz=null;relationView='compare';render()});$('#compareLinks').onclick=()=>{relationView='compare';renderRelations()};$('#quizLinks').onclick=()=>{relationView='quiz';renderRelations()};
 if(relationView==='quiz'){if(relationQuiz?.finished)renderLinkResults();else if(relationQuiz)renderLinkQuestion();else{$('#relationBody').innerHTML=`<div class="quiz-start"><h3>Make the connection.</h3><p>Pick the ${type==='Antonyms'?'opposite':'synonym / near-synonym'} of the Korean word. Context is shown so you can choose the right sense.</p><select id="linkQuizSize" aria-label="Number of pair questions"><option value="10">10 questions</option><option value="all">All ${pool.length} groups</option></select><button class="btn primary" id="startLinkQuiz">Start pair test →</button><p>Pair-test results save separately; your word learning marks stay yours.</p></div>`;$('#startLinkQuiz').onclick=()=>{const count=$('#linkQuizSize').value;relationQuiz={items:shuffle(pool).slice(0,count==='all'?pool.length:+count),at:0,results:[],answered:false,finished:false};renderLinkQuestion()}}return}
 $('#relationBody').innerHTML=`<button class="text-link" id="toggleLinkMeanings">${window.linkMeaningsHidden?'Reveal meanings':'Hide meanings for recall'}</button><div class="relation-groups">${pool.map(g=>{const p=state.linkPractice[g.id]||{correct:0,wrong:0};return `<article class="relation-group"><div class="card-meta"><span>${g.near?'NEAR SYNONYMS':g.type.toUpperCase()}</span><span>PAIR PRACTICE · ✓ ${p.correct} · ↺ ${p.wrong}</span></div><div class="relation-terms">${g.terms.map((t,i)=>`${i?`<span class="relation-symbol">${g.type==='Antonyms'?'↔':'≈'}</span>`:''}<div><strong lang="ko">${e(t.korean)}</strong><p>${window.linkMeaningsHidden?'…':e(t.meaning)}</p>${!t.cardId?'<small>Extra comparison</small>':''}</div>`).join('')}</div>${g.note&&!window.linkMeaningsHidden?`<p class="relation-note">${e(g.note)}</p>`:''}</article>`}).join('')}</div>`;$('#toggleLinkMeanings').onclick=()=>{window.linkMeaningsHidden=!window.linkMeaningsHidden;renderRelations()};
}
function renderLinkQuestion(){const g=relationQuiz.items[relationQuiz.at],target=g.terms[0],answer=g.terms[1];if(!relationQuiz.answered){const excluded=new Set(g.terms.map(t=>t.korean)),all=[...new Set(relationGroups.flatMap(r=>r.terms.map(t=>t.korean)))];relationQuiz.choices=shuffle([answer.korean,...shuffle(all.filter(k=>!excluded.has(k))).slice(0,3)])}
 $('#relationBody').innerHTML=`<div class="card-meta"><span>PAIR ${relationQuiz.at+1} / ${relationQuiz.items.length}</span><span>${g.near?'NEAR SYNONYM':g.type==='Antonyms'?'OPPOSITE':'SYNONYM'}</span></div><div class="quiz-word"><div class="card-language">FIND THE ${g.type==='Antonyms'?'OPPOSITE':'SYNONYM / NEAR-SYNONYM'}</div><div class="korean" lang="ko">${e(target.korean)}</div><div class="forms">In this sense: ${e(target.meaning)}</div></div><div class="choices">${relationQuiz.choices.map((k,i)=>`<button class="choice ${relationQuiz.answered?(k===answer.korean?'correct':k===relationQuiz.selected?'wrong':''):''}" data-linkanswer="${i}" ${relationQuiz.answered?'disabled':''}><span>${i+1}</span>${e(k)}</button>`).join('')}</div>${relationQuiz.answered?`<div class="feedback"><strong>${relationQuiz.selected===answer.korean?'✓ Connection made!':'↺ A useful connection to review.'}</strong><p>${g.terms.map(t=>e(t.korean)+' = '+e(t.meaning)).join('<br>')}</p><p>${e(g.note)}</p></div><button class="btn primary" id="linkNext">${relationQuiz.at===relationQuiz.items.length-1?'See results':'Next pair →'}</button>`:''}`;
 document.querySelectorAll('[data-linkanswer]').forEach(b=>b.onclick=()=>answerLink(+b.dataset.linkanswer));if($('#linkNext'))$('#linkNext').onclick=()=>{relationQuiz.at++;relationQuiz.answered=false;if(relationQuiz.at===relationQuiz.items.length){relationQuiz.finished=true;renderLinkResults()}else renderLinkQuestion()};
}
function answerLink(i){if(!relationQuiz||relationQuiz.answered||relationQuiz.finished)return;const g=relationQuiz.items[relationQuiz.at],chosen=relationQuiz.choices[i];if(chosen===undefined)return;const correct=chosen===g.terms[1].korean;relationQuiz.answered=true;relationQuiz.selected=chosen;relationQuiz.results.push({id:g.id,correct});const p=state.linkPractice[g.id]||{correct:0,wrong:0};p[correct?'correct':'wrong']++;p.lastAt=new Date().toISOString();state.linkPractice[g.id]=p;save();renderLinkQuestion()}
function renderLinkResults(){const wrong=relationQuiz.results.filter(r=>!r.correct),score=relationQuiz.results.length-wrong.length;$('#relationBody').innerHTML=`<div class="result"><div class="eyebrow">PAIR TEST COMPLETE</div><div class="score">${score}<small style="font-size:23px"> / ${relationQuiz.results.length}</small></div><h3>Every connection makes recall easier.</h3><button class="btn primary" id="newLinkTest">New pair test</button>${wrong.length?' <button class="btn" id="retryLinkTest">Retry missed pairs</button>':''}${wrong.map(r=>{const g=relationGroups.find(g=>g.id===r.id);return `<div class="mistake-row">${g.terms.map(t=>e(t.korean)+' = '+e(t.meaning)).join('<br>')}</div>`}).join('')}</div>`;$('#newLinkTest').onclick=()=>{relationQuiz=null;renderRelations()};if($('#retryLinkTest'))$('#retryLinkTest').onclick=()=>{relationQuiz={items:shuffle(wrong.map(r=>relationGroups.find(g=>g.id===r.id))),at:0,results:[],answered:false,finished:false};renderLinkQuestion()}}

function showDialog(html){$('#dialogContent').innerHTML=html;$('#dialog').showModal()}
const sourceLabel=p=>collection.textSources?.[p]?.label||'IMG_'+p;
const sourceVisual=p=>collection.textSources?.[p]?`<pre class="typed-source">${e(collection.textSources[p].text)}</pre>`:`<img class="source-photo" id="sourcePhoto" src="pages/${p}.jpg" alt="Original notebook photo ${e(sourceLabel(p))}">`;
function sources(pages=null,w=null){if(w?.studyRef){showDialog(`<h2>${e(w.korean)} · Chapter ${w.studyRef.chapter}</h2><p>Korean Made Easy · ${e(w.studyRef.part)} · study day ${e(w.studyRef.date)}</p><p translate="no">${e(w.answer)}</p><p translate="no">${e(w.note)}</p>`);return}if(w?.hanjaRef){showDialog(`<h2>${e(w.korean)} · Hanja book</h2><p>Useful Hanja for Learners of Korean · Chapter ${w.hanjaRef.chapter} · printed page ${w.hanjaRef.page}</p><p translate="no">${e(w.note)}</p><p>${e(w.quizAnswer)}</p>`);return}const ps=pages||[...collection.pages,...Object.keys(collection.textSources||{})];let p=ps[0];showDialog(`<h2>${w?e(w.korean)+' · Original notes':'Your notebook pages'}</h2><p>${w?`${w.count} recorded appearance${w.count===1?'':'s'}. ${w.learned?'At least one has a tick in your notebook.':'No ticks recorded.'}`:`${collection.photos} source photos covering ${collection.notebookPages||collection.photos} notebook pages. Extended photos add new rows; overlapping rows are not counted again.`}</p>${w?`<div>${w.occurrences.map(o=>`<p><strong>${e(sourceLabel(o.page))}</strong> · ${e(o.written)} → ${e(o.meaning)} ${o.ticked?'✓ ticked':''}</p>`).join('')}</div>`:''}<div class="page-buttons">${ps.map(n=>`<button data-photo="${n}" class="${n===p?'active':''}">${e(sourceLabel(n))}</button>`).join('')}</div><div id="sourcePreview">${sourceVisual(p)}</div><p>Repeated words are counted across main pages and repeated rows. A noun and verb written in one row count as one appearance. Related noun/verb forms are grouped on one card and labelled; every original form remains in the source record. Slash-separated words have their own cards. Ticks are preserved as the starting learned status.</p><p>Study notes retain the wording on your paper. <a href="https://krdict.korean.go.kr/eng/mainAction" target="_blank" rel="noopener">National Institute of Korean Language dictionary ↗</a></p>`);document.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>{p=b.dataset.photo;$('#sourcePreview').innerHTML=sourceVisual(p);document.querySelectorAll('[data-photo]').forEach(x=>x.classList.toggle('active',x===b))})}
$('.tabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;if(mode==='plan'){window.StudyHub.open('today');return}if(mode==='links'&&!['Synonyms','Antonyms'].includes(category)){category='Synonyms';$('#unlearned').checked=false;resetDeck()}render()});$('#unlearned').onchange=()=>{resetDeck();render()};$('#shuffle').onclick=()=>{deck=shuffle(filtered());index=0;flipped=false;reviewed=new Set();renderCard();toast('Fresh order, fresh start ˙ᵕ˙')};$('#restart').onclick=()=>{resetDeck();render()};$('#sourcesBtn').onclick=()=>sources();$('#closeDialog').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('click',ev=>{if(ev.target===$('#dialog')){const r=ev.target.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)ev.target.close()}});
function closeMenu(){document.body.classList.remove('menu-open');$('#menuToggle').setAttribute('aria-expanded','false');$('#menuBackdrop').hidden=true}
$('#menuToggle').onclick=()=>{const open=document.body.classList.toggle('menu-open');$('#menuToggle').setAttribute('aria-expanded',String(open));$('#menuBackdrop').hidden=!open;if(open)$('#categoryList button')?.focus()};$('#menuBackdrop').onclick=()=>{closeMenu();$('#menuToggle').focus()};document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&document.body.classList.contains('menu-open')){closeMenu();$('#menuToggle').focus()}});
$('#homeBrand').onclick=ev=>{closeMenu();ev.preventDefault();window.StudyHub.open('today')};$('#settingsBtn').onclick=()=>showDialog(`<h2>Study settings</h2><p>Progress saves in this browser. Open <b>Backups</b> in the sidebar to connect a file, download your progress, or restore a backup.</p><details><summary>Keyboard shortcuts</summary><p>Flashcards: ↑ learn again · ↓ I know it · Space flip.<br>Quiz: 1–4 choose an answer · Enter next question.</p></details><details><summary>How reviews work</summary><p>Daily vocabulary: 20 words. Yesterday’s new words are a separate set. Hanja stays separate.</p><p>Successful recall schedules another review in 1, 3, 7, 14, 28… days. A missed word returns tomorrow. Quiz results preserve your learned marks.</p></details><details><summary>Book progress</summary><p>Chapter marks track what you have covered. Each word’s recall history is tracked separately.</p></details>`);
$('#exportBtn').onclick=()=>{const blob=new Blob([JSON.stringify(snapshot(),null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='seoul-study-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Progress saved. Keep it for your next device.')};$('#importBtn').onclick=()=>$('#importFile').click();$('#importFile').onchange=async ev=>{try{const f=ev.target.files[0];if(!f)return;restoreState(JSON.parse(await f.text()));save();resetDeck();render();toast('Progress restored, including chapter marks and your own vocabulary ♡')}catch{toast('That file is not a valid study progress backup.')}ev.target.value=''};
function restoreState(data){const s=data.state;if(data.app!=='seoul-study-club'||![1,2].includes(data.version)||!s||!s.learned||typeof s.learned!=='object'||!Array.isArray(s.mistakes)||!s.daily||typeof s.daily!=='object'||!s.plan||typeof s.plan!=='object'||!/^\d{4}-\d{2}-\d{2}$/.test(s.exam))throw Error('Invalid backup');
 if(window.Vocabulary){state.customWords=window.Vocabulary.normalize(s.customWords||[]);window.Vocabulary.sync()}
 if(window.ReferenceNotes)state.referenceNotes=window.ReferenceNotes.normalize(s.referenceNotes||[]);
 const ids=new Set(words.flatMap(w=>[w.id,...w.legacyIds||[]]).concat((state.customWords||[]).map(w=>w.id)));state.learned=Object.fromEntries(Object.entries(s.learned).filter(([k,v])=>ids.has(k)&&typeof v==='boolean'));state.mistakes=s.mistakes.filter(k=>ids.has(k));state.daily=Object.fromEntries(Object.entries(s.daily).filter(([k,v])=>/^\d{4}-\d{2}-\d{2}$/.test(k)&&Array.isArray(v)).map(([k,v])=>[k,v.filter(id=>ids.has(id))]));state.plan=Object.fromEntries(Object.entries(s.plan).filter(([k,v])=>['0','1','2','3'].includes(k)&&typeof v==='boolean'));state.exam=s.exam;state.updatedAt=Number.isFinite(s.updatedAt)?s.updatedAt:0;
 const count=n=>Number.isSafeInteger(n)&&n>=0?n:0;
 state.practice=Object.fromEntries(Object.entries(s.practice||{}).filter(([id,p])=>ids.has(id)&&p&&typeof p==='object').map(([id,p])=>[id,{known:count(p.known),again:count(p.again),forgotten:count(p.forgotten),lastAction:p.lastAction==='known'?'known':'again',lastAt:typeof p.lastAt==='string'?p.lastAt:'',history:Array.isArray(p.history)?p.history.filter(h=>h&&['known','again'].includes(h.action)&&typeof h.at==='string').slice(-100):[]}]));
 if(window.StudyEngine)state.curriculum=window.StudyEngine.normalize(s.curriculum||state.curriculum,today());
 const linkIds=new Set(relationGroups.map(g=>g.id));state.linkPractice=Object.fromEntries(Object.entries(s.linkPractice||{}).filter(([id,p])=>linkIds.has(id)&&p&&typeof p==='object').map(([id,p])=>[id,{correct:count(p.correct),wrong:count(p.wrong),lastAt:typeof p.lastAt==='string'?p.lastAt:''}]));
 migrationPerformed=window.migrateStudyProgress(state,words)||migrationPerformed;
 try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}
}
const storage=window.createProgressStorage({getSnapshot:snapshot,restoreSnapshot:restoreState,onStatus:(text,kind)=>{$('#saveStatus').textContent=text;$('#saveStatus').dataset.kind=kind;$('#connectFile').textContent=kind==='resume'?'Resume file saving':kind==='file'||kind==='saving'?'Change progress file':'Connect progress file'},onExistingFile:file=>new Promise(resolve=>{
 showDialog(`<h2>${file.unrecognised?'This file isn’t a study backup.':'This file already has progress.'}</h2><p>${file.unrecognised?'Choose another file to keep its current contents.':'Restore its saved progress, or replace it with the progress currently in this Chrome browser.'}</p>${file.unrecognised?'':'<button class="btn primary" id="useFileProgress">Restore file progress</button> <button class="btn" id="useBrowserProgress">Save browser progress instead</button>'}<button class="text-link" id="cancelFile">Cancel</button>`);
 let done=false;const finish=choice=>{if(done)return;done=true;$('#dialog').close();resolve(choice)};
 if($('#useFileProgress'))$('#useFileProgress').onclick=()=>finish('restore');if($('#useBrowserProgress'))$('#useBrowserProgress').onclick=()=>finish('browser');$('#cancelFile').onclick=()=>finish('cancel');$('#dialog').addEventListener('close',()=>finish('cancel'),{once:true});
})});
$('#connectFile').onclick=async()=>{await storage.connect(['file','saving'].includes($('#saveStatus').dataset.kind));resetDeck();render()};$('#backupTop').onclick=()=>$('#exportBtn').click();$('#restoreLatest').onclick=()=>$('#importFile').click();$('#restorePublished').onclick=async()=>{try{const backup=await window.ProgressSeed.load();showDialog(`<h2>Restore published progress?</h2><p>This replaces the progress currently in Chrome with the 26 October backup. Download your current backup first if you need it.</p><button class="btn primary" id="confirmPublished">Restore published backup</button> <button class="small-btn" id="cancelPublished">Cancel</button>`);$('#cancelPublished').onclick=()=>$('#dialog').close();$('#confirmPublished').onclick=()=>{localStorage.setItem(KEY+'-before-published-restore',JSON.stringify(snapshot()));restoreState(backup);save();resetDeck();$('#dialog').close();render();toast('Published backup restored.')};}catch{toast('Could not load the published backup. Your current progress is unchanged.')}};
document.addEventListener('keydown',ev=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||$('#dialog').open||ev.ctrlKey||ev.metaKey||ev.altKey||ev.repeat)return;
 if(mode==='cards'){
  const actions={ArrowUp:'#again',ArrowDown:'#know',ArrowRight:'#next',ArrowLeft:'#prev'};
  if(actions[ev.key]){ev.preventDefault();const button=$(actions[ev.key]);if(button&&!button.disabled)button.click()}
  else if(ev.code==='Space'&&document.activeElement?.tagName!=='BUTTON'){$('#flip')?.click();ev.preventDefault()}
 }else if(mode==='links'&&relationQuiz&&!relationQuiz.finished){if(/^[1-4]$/.test(ev.key))answerLink(+ev.key-1);if(ev.key==='Enter'&&document.activeElement?.tagName!=='BUTTON')$('#linkNext')?.click()}else if(mode==='quiz'&&quiz&&!quiz.finished){if(/^[1-4]$/.test(ev.key))answerQuiz(+ev.key-1);if(ev.key==='Enter'&&document.activeElement?.tagName!=='BUTTON')$('#quizNext')?.click()}
});
$('#studyContent').innerHTML='<div class="loading">Opening your study room… ˙ᵕ˙</div>';
Promise.all(['words.json','collection.json','relations.json','hanja.json','exam-dates.json','book-notes.json'].map(name=>fetch(name,{cache:'no-store'}).then(r=>{if(!r.ok)throw Error(name);return r.json()}))).then(async([data,meta,links,hanja,examDates,notes])=>{words=data;collection=meta;relationGroups=links;const extra=window.StudyHub.init(hanja,examDates);words=[...words,...extra,...window.BookNotes.init(notes)];state.customWords=window.Vocabulary.normalize(state.customWords);window.Vocabulary.sync();migrationPerformed=window.migrateStudyProgress(state,words);await storage.start();try{const published=await window.ProgressSeed.load();if(window.ProgressSeed.shouldRestore(state,published)){try{localStorage.setItem(KEY+'-before-published-restore',JSON.stringify(snapshot()))}catch{}restoreState(published);save()}}catch(err){console.warn('Published backup could not be loaded; browser progress kept.',err)}state.curriculum=window.StudyEngine.normalize(state.curriculum,today());const noteSeeded=window.BookNotes.seed(state.curriculum),referenceSeeded=window.ReferenceNotes.sync();if(window.StudyHub.seedReviews()||migrationPerformed||noteSeeded||referenceSeeded)save();resetDeck();render()}).catch(err=>{$('#studyContent').innerHTML='<div class="empty">The study room couldn’t load. Please refresh; your saved progress has not been cleared.</div>';console.error(err)});
